<?php
declare(strict_types=1);
require_once __DIR__.'/admin/bootstrap.php';
hamed_headers();hamed_https();
$lock=__DIR__.'/admin/installed.lock';$configFile=__DIR__.'/admin/install-config.php';
if(is_file($lock)||is_file($configFile)||is_link($lock)||is_link($configFile)){http_response_code(410);exit('نصب قبلاً انجام شده یا پیکربندی موجود است. فایل install.php را پس از نصب حذف کنید.');}
if(!hamed_setup_authorized()){
 http_response_code(403);header('Content-Type: text/html; charset=utf-8');
 exit('<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>محافظت نصب</title><link rel="stylesheet" href="/admin/admin.css"></head><body><main class="admin-shell"><section class="setup-card"><h1>ابتدا دسترسی نصب را محافظت کنید</h1><p>برای نصب روی هاست، در cPanel بخش Directory Privacy را برای ریشهٔ سایت فعال کنید و با حساب خصوصی آن وارد شوید. هنگام استخراج بسته، قواعد احراز هویت آن در .htaccess باید حفظ شوند.</p><p>PHP باید کاربر تأییدشدهٔ وب‌سرور را در REMOTE_USER دریافت کند؛ اگر با وجود Directory Privacy این پیام را می‌بینید، از پشتیبانی هاست بخواهید این تنظیم را اصلاح کند.</p><p>پس از نصب موفق، install.php را حذف کنید و سپس محافظت موقت را بردارید.</p></section></main></body></html>');
}
hamed_session();
if(!isset($_SESSION['install_csrf'])||!is_string($_SESSION['install_csrf']))$_SESSION['install_csrf']=bin2hex(random_bytes(32));$token=$_SESSION['install_csrf'];$error='';$done=false;
function h(string $s):string{return htmlspecialchars($s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function posted(string $key,string $default=''):string{$v=hamed_field($_POST,$key);return $v===null?$default:$v;}
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
 if((int)($_SERVER['CONTENT_LENGTH']??0)>16384)$error='حجم فرم نصب بیش از حد مجاز است.';
 elseif(!is_string($_POST['csrf']??null)||!hash_equals($token,$_POST['csrf']))$error='فرم منقضی شده است؛ صفحه را تازه کنید.';
 else {
  $hostDb=trim(posted('db_host'));$dbName=trim(posted('db_name'));$dbUser=trim(posted('db_user'));$dbPass=posted('db_pass');$username=trim(posted('admin_user'));$password=posted('admin_pass');$confirm=posted('admin_confirm');
  if(array_filter(['db_host','db_name','db_user','db_pass','admin_user','admin_pass','admin_confirm'],static fn($key)=>hamed_field($_POST,$key)===null))$error='فرم نصب معتبر نیست.';
  elseif(!preg_match('/\A[A-Za-z0-9_.:-]{1,190}\z/',$hostDb)||!preg_match('/\A[A-Za-z0-9_$-]{1,64}\z/',$dbName)||!preg_match('/\A[A-Za-z0-9_$-]{1,64}\z/',$dbUser)||strlen($dbPass)>1024||str_contains($dbPass,"\0"))$error='مقادیر اتصال دیتابیس معتبر نیستند.';
  elseif(!preg_match('/\A[A-Za-z0-9_.-]{3,64}\z/',$username))$error='نام کاربری مدیر باید ۳ تا ۶۴ نویسهٔ انگلیسی، عدد، نقطه، خط تیره یا زیرخط باشد.';
  elseif(!in_array('mysql',PDO::getAvailableDrivers(),true)||!extension_loaded('fileinfo')||!extension_loaded('mbstring'))$error='افزونه‌های pdo_mysql، fileinfo و mbstring باید روی PHP فعال باشند.';
  elseif(!mb_check_encoding($password,'UTF-8')||mb_strlen($password,'UTF-8')<14||strlen($password)>72||str_contains($password,"\0")||$password!==$confirm)$error='گذرواژه باید دست‌کم ۱۴ نویسه و حداکثر ۷۲ بایت UTF-8 باشد و دو بار یکسان وارد شود؛ یک عبارت انگلیسی طولانی مناسب است.';
  elseif(is_file($configFile))$error='پیکربندی از قبل وجود دارد؛ برای جلوگیری از بازنویسی نصب متوقف شد.';
  else {
   $writtenConfig=false;$writtenLock=false;$guard=null;
   try{
    $guard=@fopen(__DIR__.'/admin/setup.guard','c');if(!is_resource($guard)||!flock($guard,LOCK_EX))throw new RuntimeException('Setup lock unavailable');
    if(file_exists($lock)||is_link($lock)||file_exists($configFile)||is_link($configFile))throw new RuntimeException('Existing installation');
    $pdo=new PDO('mysql:host='.$hostDb.';dbname='.$dbName.';charset=utf8mb4',$dbUser,$dbPass,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
    $pdo->exec("CREATE TABLE IF NOT EXISTS admin_users (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS settings (setting_key VARCHAR(40) NOT NULL PRIMARY KEY, setting_value VARCHAR(2048) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS downloads (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, filename VARCHAR(124) NOT NULL UNIQUE, title_fa VARCHAR(360) NOT NULL, title_en VARCHAR(360) NOT NULL, size_bytes BIGINT UNSIGNED NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS login_attempts (ip_hash CHAR(64) NOT NULL PRIMARY KEY, attempts INT UNSIGNED NOT NULL, window_start BIGINT UNSIGNED NOT NULL, blocked_until BIGINT UNSIGNED NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->beginTransaction();if((int)$pdo->query('SELECT COUNT(*) FROM admin_users')->fetchColumn()!==0)throw new RuntimeException('Existing administrator preserved');$q=$pdo->prepare('INSERT INTO admin_users(username,password_hash) VALUES(?,?)');$q->execute([$username,password_hash($password,PASSWORD_DEFAULT)]);
    $q=$pdo->prepare('INSERT IGNORE INTO settings(setting_key,setting_value) VALUES(?,?)');foreach(hamed_defaults() as $k=>$v)$q->execute([$k,$v]);
    $cfg="<?php\ndeclare(strict_types=1);\nif (!defined('HAMED_BOOTSTRAP')) { http_response_code(404); exit; }\nreturn ".var_export(['host'=>$hostDb,'name'=>$dbName,'user'=>$dbUser,'password'=>$dbPass],true).";\n";
    $handle=@fopen($configFile,'x+b');if(!is_resource($handle))throw new RuntimeException('Configuration already exists');$writtenConfig=true;try{if(fwrite($handle,$cfg)!==strlen($cfg)||!fflush($handle))throw new RuntimeException('Configuration write failed');}finally{fclose($handle);}chmod($configFile,0640);
    $handle=@fopen($lock,'x+b');if(!is_resource($handle))throw new RuntimeException('Install marker already exists');$writtenLock=true;try{$marker='installed '.gmdate('c');if(fwrite($handle,$marker)!==strlen($marker)||!fflush($handle))throw new RuntimeException('Install marker write failed');}finally{fclose($handle);}chmod($lock,0640);$pdo->commit();$done=true;$_SESSION['install_csrf']=bin2hex(random_bytes(32));session_regenerate_id(true);
   }catch(Throwable){if(isset($pdo)&&$pdo instanceof PDO&&$pdo->inTransaction())$pdo->rollBack();if($writtenConfig)@unlink($configFile);if($writtenLock)@unlink($lock);$error='نصب کامل نشد. مشخصات دیتابیس، خالی بودن جدول مدیران و دسترسی نوشتن پوشهٔ admin را بررسی کنید؛ جزئیات اتصال نمایش داده نمی‌شود.';}
   finally{if(is_resource($guard)){flock($guard,LOCK_UN);fclose($guard);}}
  }
 }
}
?><!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><title>نصب سایت | حامد قاسم‌زاده</title><link rel="stylesheet" href="/admin/admin.css"></head><body><main class="admin-shell"><header class="admin-header"><a class="admin-brand" href="/"><span class="brand-mark">H</span><span><strong>نصب سایت رزومه</strong><small>راه‌اندازی امن پایگاه داده</small></span></a></header>
<?php if($done):?><section class="setup-card"><p class="eyebrow">نصب کامل شد</p><h1>سایت آمادهٔ استفاده است</h1><p>پیکربندی دیتابیس و حساب مدیر ساخته شد. برای امنیت، اکنون فایل <code>install.php</code> را از هاست حذف کنید و سپس وارد پنل شوید.</p><a class="button button-primary" href="/admin/">ورود به پنل مدیر ←</a></section>
<?php else: ?><section class="setup-card"><p class="eyebrow">راه‌اندازی یک‌باره</p><h1>اتصال پایگاه داده و ساخت مدیر</h1><p>ابتدا در cPanel یک دیتابیس MySQL و کاربر بسازید و دسترسی کامل کاربر به دیتابیس را بدهید. سپس اطلاعات را در این فرم وارد کنید.</p><?php if($error!==''):?><p class="form-status" role="alert"><?=h($error)?></p><?php endif;?><form method="post" autocomplete="off"><input type="hidden" name="csrf" value="<?=h($token)?>"><label for="db-host">میزبان دیتابیس</label><input id="db-host" name="db_host" required value="<?=h(posted('db_host','localhost'))?>" autocomplete="off"><label for="db-name">نام دیتابیس</label><input id="db-name" name="db_name" required value="<?=h(posted('db_name'))?>"><label for="db-user">کاربر دیتابیس</label><input id="db-user" name="db_user" required value="<?=h(posted('db_user'))?>"><label for="db-pass">گذرواژهٔ دیتابیس</label><input id="db-pass" name="db_pass" type="password" required autocomplete="new-password"><hr><label for="admin-user">نام کاربری مدیر</label><input id="admin-user" name="admin_user" required minlength="3" maxlength="64" value="<?=h(posted('admin_user'))?>" autocomplete="username"><label for="admin-pass">گذرواژهٔ مدیر</label><input id="admin-pass" name="admin_pass" type="password" required minlength="14" maxlength="72" autocomplete="new-password"><label for="admin-confirm">تکرار گذرواژه</label><input id="admin-confirm" name="admin_confirm" type="password" required minlength="14" maxlength="72" autocomplete="new-password"><button class="button button-primary" type="submit">بررسی اتصال و نصب</button></form><p class="setup-note">اطلاعات دیتابیس داخل پوشهٔ محافظت‌شدهٔ admin ذخیره می‌شود. نصب فقط ساختار و مقادیر آغازین را اضافه می‌کند و هیچ جدول یا داده‌ای را حذف نمی‌کند.</p></section><?php endif;?><footer class="admin-footer"><span>Hamed Ghasemzadeh</span><a href="/">بازگشت به سایت</a></footer></main></body></html>
